const p = $('Plan Listing').item.json;
const r = $json;
if (r.error_summary) throw new Error('list_folder failed for "' + p.name + '": ' + r.error_summary);

const VID = /\.(mp4|mov|m4v)$/i;
const NOCAP = /(before|without|no|w\/o|pre)[\s_.-]*cap/i;
const CAPNAME = /(^|[^a-z])(cap|caps|captions?|captioned|subs|subtitled)([^a-z]|$)/i;
const JUNK = /(^|[^a-z])(test|testing|tmp|temp|proxy|preview|sample|draft|copy|old|backup|bkp|scratch|untitled)([^a-z]|$)/i;
const TOPAZ = /(?:^|[^a-z])topaz(?:[^a-z]|$)/i;
const MIN_SIZE = 10 * 1048576;

const fp = p.folderPath;
const root = p.useParent ? p.parent : fp;
const ver = n => {
  const m = n.match(/(?:^|[^a-z])v\s?(\d+)(?:[._-](\d+))?/i) || n.match(/V(\d+)(?:[._-](\d+))?/);
  return m ? [parseInt(m[1], 10), parseInt(m[2] || '0', 10)] : null;
};
const key = s => { const m = (s || '').toLowerCase().match(/^\s*([a-z]+)\s*(\d+)/); return m ? m[1] + ' ' + m[2] : null; };
const base = { itemId: p.itemId, name: p.name, folderUrl: p.folderUrl, folderSaved: p.folderSaved, skipJev: true, confidence: 1 };

// 1) Folder sanity check: "Calli 3" item must not point at a "Calli 2" folder
const folderName = fp.split('/').pop();
const ki = key(p.name), kf = key(folderName);
if (ki && kf && ki !== kf) {
  return [{ json: { ...base, files: [], pick: null, note: 'Needs review: folder "' + folderName + '" does not match item' } }];
}

// 2) Collect video files: project folder itself + any Captions folder (archive ignored)
const all = [];
for (const e of (r.entries || [])) {
  if (e['.tag'] !== 'file' || !VID.test(e.name)) continue;
  const pl = e.path_lower; if(p.directPath&&pl!==p.directPath)continue;
  if (/\.fcp\w*bundle\//.test(pl)) continue;
  const dir = pl.substring(0, pl.lastIndexOf('/'));
  if (dir !== root && !dir.startsWith(root + '/')) continue;
  const segs = dir === root ? [] : dir.slice(root.length + 1).split('/');
  const archived = segs.some(s => s === 'archive' || s === 'old');
  const inCaptions = !archived && segs.some(s => /caption/.test(s));
  const inProject = dir === fp;
